declare(strict_types=1); require_once __DIR__.'/../config/app.php'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/school_profile.php'; require_login(); require_role('admin');
$dir=__DIR__.'/../uploads/profil'; if(!is_dir($dir)) mkdir($dir,0775,true); $row=$pdo->query('SELECT * FROM profil_sekolah ORDER BY id LIMIT 1')->fetch() ?: [];$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$fields=['nama_sekolah','npsn','nss','jenjang','status_sekolah','alamat','desa','kecamatan','kabupaten','provinsi','kode_pos','telepon','email','website','nama_kepala','nip_kepala'];$data=[];foreach($fields as $f)$data[$f]=trim((string)($_POST[$f]??''));if($data['nama_sekolah']==='')$err='Nama sekolah wajib diisi.';if(!$err){$id=(int)($row['id']??0);if($id){$sql='UPDATE profil_sekolah SET '.implode(',',array_map(fn($f)=>$f.'=?',$fields)).' WHERE id=?';$st=$pdo->prepare($sql);$st->execute([...array_values($data),$id]);}else{$sql='INSERT INTO profil_sekolah ('.implode(',',$fields).') VALUES ('.implode(',',array_fill(0,count($fields),'?')).')';$st=$pdo->prepare($sql);$st->execute(array_values($data));$id=(int)$pdo->lastInsertId();}$row=$pdo->query('SELECT * FROM profil_sekolah WHERE id='.(int)$id)->fetch();foreach(['logo','foto'] as $f){if(!empty($_FILES[$f]['tmp_name'])){ $upload=$_FILES[$f]; if(($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK || !is_uploaded_file($upload['tmp_name'])){$err='Upload '.$f.' gagal.';break;} if((int)($upload['size']??0)>5*1024*1024){$err='Ukuran '.$f.' maksimal 5 MB.';break;} $mime=(new finfo(FILEINFO_MIME_TYPE))->file($upload['tmp_name']); $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; if(!isset($allowed[$mime])){$err='Format '.$f.' harus JPG, PNG, atau WEBP.';break;} if(@getimagesize($upload['tmp_name'])===false){$err='File '.$f.' bukan gambar yang valid.';break;} $ext=$allowed[$mime]; $name=$f.'_'.date('YmdHis').'_'.bin2hex(random_bytes(8)).'.'.$ext; if(!move_uploaded_file($upload['tmp_name'],$dir.'/'.$name)){$err='Gagal menyimpan '.$f.'.';break;} $pdo->prepare("UPDATE profil_sekolah SET $f=? WHERE id=?")->execute(['uploads/profil/'.$name,$id]);$row[$f]='uploads/profil/'.$name;}}if(!$err)$msg='Profil sekolah berhasil disimpan.';}}
