control" name="nama_kepala" value="<?=e($row['nama_kepala']??'')?>"></label><label>NIP Kepala Sekolah<input class="form-control" name="nip_kepala" value="<?=e($row['nip_kepala']??'')?>"></label><label style="grid-column:1/-1">Alamat<textarea class="form-control" name="alamat" rows="3"><?=e($row['alamat']??'')?></textarea></label><label>Logo Sekolah<input class="form-control" type="file" name="logo" accept="image/*"><?php if(!empty($row['logo'])):?><img src="<?=e(school_asset_url($row['logo']))?>" alt="Logo sekolah" style="width:90px;height:90px;object-fit:contain;margin-top:8px;border:1px solid #e2e8f0;border-radius:12px;padding:6px;background:#fff"><?php endif;?></label><label>Foto Sekolah<input class="form-control" type="file" name="foto" accept="image/*"><?php if(!empty($row['foto'])):?><img src="<?=e(school_asset_url($row['foto']))?>" alt="Foto sekolah" style="width:160px;height:90px;object-fit:cover;margin-top:8px;border:1px solid #e2e8f0;border-radius:12px"><?php endif;?></label></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-check2-circle"></i> Simpan Profil Sekolah</button></div></form></div></section></main><?php require __DIR__.'/../layouts/footer.php';?>